  "admin.modelPlaceholder": { "zh-CN": "留空则使用内置默认（agnes-3.0-flash）", "zh-TW": "留空則使用內建預設（agnes-3.0-flash）", en: "Leave blank for the built-in default (agnes-3.0-flash)", fr: "Laisser vide pour le défaut intégré (agnes-3.0-flash)" },
  "admin.cloudSaveDefault": { "zh-CN": "默认开启云端保存", "zh-TW": "預設開啟雲端儲存", en: "Enable cloud sync by default", fr: "Activer la synchro cloud par défaut" },
  "admin.cloudSaveDefaultHint": { "zh-CN": "新用户是否默认把聊天记录存到服务端（用户仍可自行关闭）", "zh-TW": "新使用者是否預設把聊天記錄存到伺服器（使用者仍可自行關閉）", en: "Whether new users sync chats to the server by default (they can still turn it off)", fr: "Si les nouveaux utilisateurs synchronisent les discussions par défaut (ils peuvent le désactiver)" },
  "admin.icpTextPlaceholder": { "zh-CN": "如 京ICP备12345678号-1 / 萌ICP备20260645号，留空不显示", "zh-TW": "如 京ICP備12345678號-1 / 萌ICP備20260645號，留空不顯示", en: "e.g. 京ICP备12345678号-1 / 萌ICP备20260645号, leave blank to hide", fr: "ex. 京ICP备12345678号-1 / 萌ICP备20260645号, laisser vide pour masquer" },
  "admin.icpPasteHint": { "zh-CN": "可直接粘贴第三方备案给的整段 <a> 标签，会自动拆出链接与文字。", "zh-TW": "可直接貼上第三方備案給的整段 <a> 標籤，會自動拆出連結與文字。", en: "You can paste the whole <a> tag from a third-party registry; the link and text are split automatically.", fr: "Vous pouvez coller toute la balise <a> d'un registre tiers ; le lien et le texte sont séparés automatiquement." },
  "admin.icpUrlPlaceholder": { "zh-CN": "留空则自动指向工信部备案查询系统", "zh-TW": "留空則自動指向工信部備案查詢系統", en: "Leave blank to link to the MIIT registry", fr: "Laisser vide pour renvoyer vers le registre MIIT" },
  "admin.icpIconPlaceholder": { "zh-CN": "icp.gov.moe / icp.sakura.ink 给的图标链接（可选）", "zh-TW": "icp.gov.moe / icp.sakura.ink 給的圖示連結（選填）", en: "Icon URL from icp.gov.moe / icp.sakura.ink (optional)", fr: "URL de l'icône de icp.gov.moe / icp.sakura.ink (facultatif)" },
  "admin.icpIconHint": { "zh-CN": "可选。留空会根据备案链接自动生成徽章（萌备案显示「萌」、工信部显示「ICP」）。填了自己的图片就以图片为准，加载失败会自动退回生成的徽章，不会显示破图。", "zh-TW": "選填。留空會根據備案連結自動產生徽章（萌備案顯示「萌」、工信部顯示「ICP」）。填了自己的圖片就以圖片為準，載入失敗會自動退回產生的徽章，不會顯示破圖。", en: "Optional. Leave blank to auto-generate a badge from the ICP link (「萌」 for icp.gov.moe, 「ICP」 for MIIT). Your image wins if set, and falls back if it fails to load — no broken image.", fr: "Facultatif. Laissez vide pour générer un badge depuis le lien ICP (「萌」 pour icp.gov.moe, 「ICP」 pour le MIIT). Votre image est prioritaire, avec repli si elle échoue — aucune image cassée." },
  "admin.badgePreview": { "zh-CN": "徽章预览", "zh-TW": "徽章預覽", en: "Badge preview", fr: "Aperçu du badge" },
  "admin.badgeAlt": { "zh-CN": "备案徽章", "zh-TW": "備案徽章", en: "ICP badge", fr: "Badge ICP" },
  "admin.icpNotSet": { "zh-CN": "（未填备案号）", "zh-TW": "（未填備案號）", en: "(no ICP number)", fr: "(aucun numéro ICP)" },
  "admin.icpParsed": { "zh-CN": "已识别备案链接，请确认备案号文字", "zh-TW": "已識別備案連結，請確認備案號文字", en: "ICP link detected, please confirm the number text", fr: "Lien ICP détecté, veuillez confirmer le numéro" },
  "admin.contact": { "zh-CN": "联系方式", "zh-TW": "聯絡方式", en: "Contact method", fr: "Moyen de contact" },
