  "admin.contactValueTelegramPlaceholder": { "zh-CN": "频道或群组链接 / @用户名", "zh-TW": "頻道或群組連結 / @使用者名稱", en: "Channel or group link / @username", fr: "Lien de chaîne ou groupe / @utilisateur" },
  "admin.contactValueQqPlaceholder": { "zh-CN": "QQ 号码或群链接", "zh-TW": "QQ 號碼或群連結", en: "QQ number or group link", fr: "Numéro QQ ou lien de groupe" },
  "admin.contactHint": { "zh-CN": "Telegram 填频道/群组链接或 @用户名；QQ 填号码或群链接。识别不了就不显示，不会放出无效链接。", "zh-TW": "Telegram 填頻道/群組連結或 @使用者名稱；QQ 填號碼或群連結。辨識不了就不顯示，不會放出無效連結。", en: "Telegram: channel/group link or @username. QQ: number or group link. Unrecognized values are hidden rather than shown as dead links.", fr: "Telegram : lien de chaîne/groupe ou @utilisateur. QQ : numéro ou lien de groupe. Les valeurs non reconnues sont masquées plutôt qu'affichées en lien mort." },
  "admin.presetKeys": { "zh-CN": "站点预设 API Key", "zh-TW": "站點預設 API Key", en: "Site preset API keys", fr: "Clés API prédéfinies du site" },
  "admin.presetKeysHint": { "zh-CN": "填了之后所有访客都能直接用这些服务商的模型，不用自己填 Key。端砚与浦语是两个不同平台，Key 不通用，要分别填。", "zh-TW": "填了之後所有訪客都能直接用這些服務商的模型，不用自己填 Key。端硯與浦語是兩個不同平台，Key 不通用，要分別填。", en: "Once set, every visitor can use these providers' models without entering their own key. InkStone and Atria are separate platforms — their keys are not interchangeable and must be filled in separately.", fr: "Une fois définies, tous les visiteurs peuvent utiliser les modèles de ces fournisseurs sans saisir leur propre clé. InkStone et Atria sont deux plateformes distinctes — leurs clés ne sont pas interchangeables et doivent être saisies séparément." },
  "admin.presetFromEnv": { "zh-CN": "环境变量已配置（会压过此处填写的值）", "zh-TW": "環境變數已設定（會壓過此處填寫的值）", en: "Set via environment variable (overrides this field)", fr: "Défini via variable d'environnement (écrase ce champ)" },
  "admin.githubOauth": { "zh-CN": "GitHub 登录", "zh-TW": "GitHub 登入", en: "GitHub sign-in", fr: "Connexion GitHub" },
  "admin.githubClientIdPlaceholder": { "zh-CN": "OAuth App 的 Client ID", "zh-TW": "OAuth App 的 Client ID", en: "OAuth App Client ID", fr: "Client ID de l'app OAuth" },
  "admin.githubClientSecretPlaceholder": { "zh-CN": "OAuth App 的 Client Secret（不会下发给普通用户）", "zh-TW": "OAuth App 的 Client Secret（不會下發給一般使用者）", en: "OAuth App Client Secret (never sent to regular users)", fr: "Client Secret de l'app OAuth (jamais envoyé aux utilisateurs)" },
  "admin.githubOauthCallback": { "zh-CN": "回调地址（填到 GitHub OAuth App 后台）：", "zh-TW": "回呼位址（填到 GitHub OAuth App 後台）：", en: "Callback URL (paste into your GitHub OAuth App):", fr: "URL de rappel (à coller dans votre app OAuth GitHub) :" },
  "admin.githubFromEnv": { "zh-CN": "环境变量 GITHUB_CLIENT_ID / GITHUB_CLIENT_SECRET 已配置，会压过这里填的值。", "zh-TW": "環境變數 GITHUB_CLIENT_ID / GITHUB_CLIENT_SECRET 已設定，會蓋過這裡填的值。", en: "Env vars GITHUB_CLIENT_ID / GITHUB_CLIENT_SECRET are set and override what you fill in here.", fr: "Les variables GITHUB_CLIENT_ID / GITHUB_CLIENT_SECRET sont définies et écrasent ce que vous remplissez ici." },
  "admin.githubOauthDomains": { "zh-CN": "按域名配置（多域名）", "zh-TW": "按網域設定（多網域）", en: "Per-domain setup (multi-domain)", fr: "Configuration par domaine (multi-domaines)" },
  "admin.githubOauthDomainsHint": { "zh-CN": "GitHub OAuth App 的回调地址是固定的，一个 App 只能对应一个域名。站点用多个域名时，给每个域名各建一个 App 并填在这里；命中的域名优先于上面的全局配置和环境变量。", "zh-TW": "GitHub OAuth App 的回呼位址是固定的，一個 App 只能對應一個網域。站台使用多個網域時，請為每個網域各建立一個 App 並填在這裡；命中的網域優先於上方的全域設定與環境變數。", en: "A GitHub OAuth App has a fixed callback URL, so one app can only serve one domain. If your site runs on several domains, create an app per domain and list them here; a matched domain takes priority over the global config and env vars.", fr: "Une app OAuth GitHub a une URL de rappel fixe : une app ne peut servir qu'un seul domaine. Si votre site utilise plusieurs domaines, créez une app par domaine et listez-les ici ; un domaine correspondant est prioritaire sur la config globale et les variables d'env." },
  "admin.githubOauthDomainAdd": { "zh-CN": "添加域名", "zh-TW": "新增網域", en: "Add domain", fr: "Ajouter un domaine" },
  "admin.githubOauthDomainPlaceholder": { "zh-CN": "域名，如 chat.xyz.ci", "zh-TW": "網域，如 chat.xyz.ci", en: "Domain, e.g. chat.xyz.ci", fr: "Domaine, ex. chat.xyz.ci" },
  "admin.githubOauthDomainRemove": { "zh-CN": "删除这一条", "zh-TW": "刪除這一筆", en: "Remove this entry", fr: "Supprimer cette entrée" },
  "admin.githubOauthDomainsEmpty": { "zh-CN": "还没有按域名配置。用多个域名访问本站时，给每个域名各填一套。", "zh-TW": "尚未按網域設定。若以多個網域造訪本站，請為每個網域各填一組。", en: "No per-domain config yet. Add one entry per domain if your site is reachable on several domains.", fr: "Aucune configuration par domaine. Ajoutez une entrée par domaine si votre site est accessible sur plusieurs domaines." },
  "admin.githubOauthCurrentHost": { "zh-CN": "当前访问域名：", "zh-TW": "目前造訪網域：", en: "Current domain:", fr: "Domaine actuel :" },
  "admin.githubOauthHostMatched": { "zh-CN": "已匹配到独立配置", "zh-TW": "已對應到獨立設定", en: "Matched to a dedicated app", fr: "Associé à une app dédiée" },
  "admin.githubOauthHostFallback": { "zh-CN": "未匹配，将回退到上面的全局配置或环境变量", "zh-TW": "未對應，將退回上方的全域設定或環境變數", en: "No match — falls back to the global config or env vars", fr: "Aucune correspondance — repli sur la config globale ou les variables d'env" },

