  "api.upload.r2BindHint": { "zh-CN": "请在 wrangler.jsonc 的 r2_buckets 里绑定桶（界面部署时 Cloudflare 会自动完成绑定），然后重新部署。", "zh-TW": "請在 wrangler.jsonc 的 r2_buckets 裡綁定桶（介面部署時 Cloudflare 會自動完成綁定），然後重新部署。", en: "Bind the bucket under r2_buckets in wrangler.jsonc (Cloudflare does this automatically for dashboard deploys), then redeploy.", fr: "Liez le bucket sous r2_buckets dans wrangler.jsonc (Cloudflare le fait automatiquement pour les déploiements via l'interface), puis redéployez." },
  "api.upload.r2NotWorkers": { "zh-CN": "当前不在 Cloudflare Workers 环境，R2 只能通过 S3 兼容 API 访问，请配置 R2_BUCKET_NAME 与 API 令牌。", "zh-TW": "當前不在 Cloudflare Workers 環境，R2 只能透過 S3 相容 API 存取，請設定 R2_BUCKET_NAME 與 API 權杖。", en: "Not running on Cloudflare Workers — R2 is only reachable through the S3-compatible API, so set R2_BUCKET_NAME and an API token.", fr: "Pas d'exécution sur Cloudflare Workers — R2 n'est accessible que via l'API compatible S3, définissez R2_BUCKET_NAME et un jeton d'API." },
  "api.upload.r2Easiest": { "zh-CN": "最省事的做法：在 wrangler.jsonc 里写好 r2_buckets，桶由部署流程自动创建并绑定 —— 这样连 API 令牌都不需要。", "zh-TW": "最省事的做法：在 wrangler.jsonc 裡寫好 r2_buckets，桶由部署流程自動建立並綁定 —— 這樣連 API 權杖都不需要。", en: "Easiest route: declare r2_buckets in wrangler.jsonc — the deploy flow creates and binds the bucket for you, so no API token is needed.", fr: "Le plus simple : déclarez r2_buckets dans wrangler.jsonc — le déploiement crée et lie le bucket automatiquement, aucun jeton d'API nécessaire." },

